package domain

import "time"

// PasswordMaterial contains the derived password representation used by the
// password verifier. It deliberately has no JSON representation: password
// material is an internal authentication detail, not part of an API model.
//
// The byte slices are copied by Clone so callers do not accidentally share
// mutable credential state when a user is copied.
type PasswordMaterial struct {
	Salt       []byte `json:"-"`
	Hash       []byte `json:"-"`
	Iterations uint32 `json:"-"`
}

// Clone returns an independent copy of the password material.
func (p PasswordMaterial) Clone() PasswordMaterial {
	return PasswordMaterial{
		Salt:       append([]byte(nil), p.Salt...),
		Hash:       append([]byte(nil), p.Hash...),
		Iterations: p.Iterations,
	}
}

// PublicProfile is the safe, externally visible part of a user account.
// Password material is intentionally not present in this type.
type PublicProfile struct {
	ID            UserID    `json:"id"`
	Email         string    `json:"email"`
	EmailVerified bool      `json:"email_verified"`
	CreatedAt     time.Time `json:"created_at"`
	UpdatedAt     time.Time `json:"updated_at"`
}

// User is the complete internal user aggregate. Authentication material is
// kept separate from the public account profile and is excluded from JSON.
type User struct {
	ID               UserID           `json:"id"`
	Email            string           `json:"email"`
	EmailVerified    bool             `json:"email_verified"`
	CreatedAt        time.Time        `json:"created_at"`
	UpdatedAt        time.Time        `json:"updated_at"`
	PasswordMaterial PasswordMaterial `json:"-"`
}

// PublicProfile returns a detached profile suitable for API responses.
func (u User) PublicProfile() PublicProfile {
	return PublicProfile{
		ID:            u.ID,
		Email:         u.Email,
		EmailVerified: u.EmailVerified,
		CreatedAt:     u.CreatedAt,
		UpdatedAt:     u.UpdatedAt,
	}
}
package domain

import "errors"

// ErrorKind identifies the stable class of a domain failure.
type ErrorKind string

const (
	ErrorNotFound     ErrorKind = "not_found"
	ErrorConflict     ErrorKind = "conflict"
	ErrorInvalid      ErrorKind = "invalid"
	ErrorUnauthorized ErrorKind = "unauthorized"
)

var (
	ErrNotFound     = &DomainError{Kind: ErrorNotFound}
	ErrConflict     = &DomainError{Kind: ErrorConflict}
	ErrInvalid      = &DomainError{Kind: ErrorInvalid}
	ErrUnauthorized = &DomainError{Kind: ErrorUnauthorized}
)

// DomainError is a typed error with a stable kind suitable for mapping to an
// HTTP error envelope. Details are optional and should not contain secrets.
type DomainError struct {
	Kind  ErrorKind
	Msg   string
	Cause error
}

func (e *DomainError) Error() string {
	if e.Msg != "" {
		return e.Msg
	}
	return string(e.Kind)
}

func (e *DomainError) Unwrap() error { return e.Cause }

// Is lets callers use errors.Is while retaining the more specific Kind.
func (e *DomainError) Is(target error) bool {
	other, ok := target.(*DomainError)
	return ok && e.Kind == other.Kind
}

// NewError annotates a stable error kind with a safe, human-readable message.
func NewError(kind ErrorKind, message string) error {
	return &DomainError{Kind: kind, Msg: message}
}

func IsKind(err error, kind ErrorKind) bool {
	var domainErr *DomainError
	return errors.As(err, &domainErr) && domainErr.Kind == kind
}

func IsNotFound(err error) bool     { return IsKind(err, ErrorNotFound) }
func IsConflict(err error) bool     { return IsKind(err, ErrorConflict) }
func IsInvalid(err error) bool      { return IsKind(err, ErrorInvalid) }
func IsUnauthorized(err error) bool { return IsKind(err, ErrorUnauthorized) }
// Package repository contains the in-memory persistence used by the IAM
// application.
package repository

import (
	"strings"
	"sync"

	"benchmark.local/iam/internal/domain"
)

// UserRepository is a concurrency-safe in-memory store for users. The email
// index contains normalized addresses and is maintained under the same lock
// as users, so an email cannot be claimed by two users.
type UserRepository struct {
	mu         sync.RWMutex
	users      map[domain.UserID]domain.User
	emailIndex map[string]domain.UserID
}

// NewUserRepository creates an empty user repository.
func NewUserRepository() *UserRepository {
	return &UserRepository{
		users:      make(map[domain.UserID]domain.User),
		emailIndex: make(map[string]domain.UserID),
	}
}

// Create stores a user and reserves its normalized email address.
func (r *UserRepository) Create(user domain.User) error {
	if r == nil {
		return domain.NewError(domain.ErrorInvalid, "user repository is nil")
	}
	if user.ID == "" || strings.TrimSpace(user.Email) == "" {
		return domain.NewError(domain.ErrorInvalid, "user id and email are required")
	}
	key := normalizeEmail(user.Email)

	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.users[user.ID]; exists {
		return domain.NewError(domain.ErrorConflict, "user already exists")
	}
	if _, exists := r.emailIndex[key]; exists {
		return domain.NewError(domain.ErrorConflict, "email already exists")
	}
	// Store both the aggregate and its credential byte slices detached from the
	// caller. This keeps later caller mutations from bypassing repository lock.
	user.Email = key
	r.users[user.ID] = cloneUser(user)
	r.emailIndex[key] = user.ID
	return nil
}

// GetByID returns a detached copy of the user with the supplied ID.
func (r *UserRepository) GetByID(id domain.UserID) (domain.User, error) {
	if r == nil {
		return domain.User{}, domain.ErrNotFound
	}
	r.mu.RLock()
	defer r.mu.RUnlock()
	user, ok := r.users[id]
	if !ok {
		return domain.User{}, domain.ErrNotFound
	}
	return cloneUser(user), nil
}

// GetByEmail returns a detached copy of the user matching the normalized
// email address. Lookup is case-insensitive and ignores surrounding spaces.
func (r *UserRepository) GetByEmail(email string) (domain.User, error) {
	if r == nil {
		return domain.User{}, domain.ErrNotFound
	}
	key := normalizeEmail(email)
	r.mu.RLock()
	defer r.mu.RUnlock()
	id, ok := r.emailIndex[key]
	if !ok {
		return domain.User{}, domain.ErrNotFound
	}
	return cloneUser(r.users[id]), nil
}

// Update replaces an existing user and, atomically, updates its email index.
// A changed email must not already belong to another user.
func (r *UserRepository) Update(user domain.User) error {
	if r == nil {
		return domain.NewError(domain.ErrorInvalid, "user repository is nil")
	}
	if user.ID == "" || strings.TrimSpace(user.Email) == "" {
		return domain.NewError(domain.ErrorInvalid, "user id and email are required")
	}
	key := normalizeEmail(user.Email)

	r.mu.Lock()
	defer r.mu.Unlock()
	previous, exists := r.users[user.ID]
	if !exists {
		return domain.ErrNotFound
	}
	if owner, claimed := r.emailIndex[key]; claimed && owner != user.ID {
		return domain.NewError(domain.ErrorConflict, "email already exists")
	}
	if oldKey := normalizeEmail(previous.Email); oldKey != key {
		delete(r.emailIndex, oldKey)
	}
	user.Email = key
	r.users[user.ID] = cloneUser(user)
	r.emailIndex[key] = user.ID
	return nil
}

// Delete removes a user and releases its email address.
func (r *UserRepository) Delete(id domain.UserID) error {
	if r == nil {
		return domain.ErrNotFound
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	user, ok := r.users[id]
	if !ok {
		return domain.ErrNotFound
	}
	delete(r.users, id)
	delete(r.emailIndex, normalizeEmail(user.Email))
	return nil
}

func normalizeEmail(email string) string {
	return strings.ToLower(strings.TrimSpace(email))
}

func cloneUser(user domain.User) domain.User {
	user.PasswordMaterial = user.PasswordMaterial.Clone()
	return user
}

// Package app assembles the process-level service dependencies.
package app

import (
	"net/http"

	"benchmark.local/iam/internal/config"
	"benchmark.local/iam/internal/domain"
)

// App is the assembled IAM application. Domain dependencies are added here as
// their packages are introduced by subsequent implementation tasks.
type App struct {
	Config  config.Config
	Clock   domain.Clock
	Handler http.Handler
}

// New builds the application from validated configuration.
func New(cfg config.Config) *App {
	return NewWithClock(cfg, domain.RealClock{})
}

// NewWithClock assembles the application with an explicit time dependency.
// Tests and domain services can therefore use a deterministic clock.
func NewWithClock(cfg config.Config, clock domain.Clock) *App {
	if clock == nil {
		clock = domain.RealClock{}
	}
	return &App{Config: cfg, Clock: clock, Handler: http.NewServeMux()}
}

// Package domain contains the small, dependency-free building blocks shared
// by the IAM domain services.
package domain

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"strings"
)

// ID is an opaque, globally unique domain identifier. Its value is a UUID
// formatted string, generated from cryptographically secure random bytes.
type ID string

// NewID creates a random UUID (version 4, variant 1).
func NewID() (ID, error) {
	var bytes [16]byte
	if _, err := rand.Read(bytes[:]); err != nil {
		return "", fmt.Errorf("generate domain id: %w", err)
	}
	bytes[6] = (bytes[6] & 0x0f) | 0x40
	bytes[8] = (bytes[8] & 0x3f) | 0x80
	var encoded [36]byte
	hex.Encode(encoded[0:8], bytes[0:4])
	encoded[8] = '-'
	hex.Encode(encoded[9:13], bytes[4:6])
	encoded[13] = '-'
	hex.Encode(encoded[14:18], bytes[6:8])
	encoded[18] = '-'
	hex.Encode(encoded[19:23], bytes[8:10])
	encoded[23] = '-'
	hex.Encode(encoded[24:36], bytes[10:16])
	return ID(encoded[:]), nil
}

// ParseID validates and returns a canonical UUID-form ID.
func ParseID(value string) (ID, error) {
	value = strings.ToLower(strings.TrimSpace(value))
	if len(value) != 36 || value[8] != '-' || value[13] != '-' || value[18] != '-' || value[23] != '-' {
		return "", fmt.Errorf("invalid domain id")
	}
	var bytes [16]byte
	if _, err := hex.Decode(bytes[:], []byte(strings.ReplaceAll(value, "-", ""))); err != nil {
		return "", fmt.Errorf("invalid domain id")
	}
	return ID(value), nil
}

// Typed IDs prevent accidentally using an identifier from another aggregate.
type UserID ID
type OrganizationID ID
type MembershipID ID
type SessionID ID
type RoleID ID
type APIKeyID ID

func NewUserID() (UserID, error)                 { id, err := NewID(); return UserID(id), err }
func NewOrganizationID() (OrganizationID, error) { id, err := NewID(); return OrganizationID(id), err }
func NewMembershipID() (MembershipID, error)     { id, err := NewID(); return MembershipID(id), err }
func NewSessionID() (SessionID, error)           { id, err := NewID(); return SessionID(id), err }
func NewRoleID() (RoleID, error)                 { id, err := NewID(); return RoleID(id), err }
func NewAPIKeyID() (APIKeyID, error)             { id, err := NewID(); return APIKeyID(id), err }
package domain

import "time"

// Clock supplies time to domain logic. Passing it as a dependency keeps
// expiration and timestamp behavior deterministic without global clock calls.
type Clock interface {
	Now() time.Time
}

// RealClock is the production clock.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now() }
// Command imad runs the IAM HTTP service.
package main

import (
	"context"
	"errors"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"

	"benchmark.local/iam/internal/app"
	"benchmark.local/iam/internal/config"
)

func main() {
	cfg, err := config.Load()
	if err != nil {
		log.Printf("configuration error: %v", err)
		return
	}

	service := app.New(cfg)
	server := &http.Server{
		Addr:         cfg.Address,
		Handler:      service.Handler,
		ReadTimeout:  cfg.ReadTimeout,
		WriteTimeout: cfg.WriteTimeout,
		IdleTimeout:  cfg.IdleTimeout,
	}

	stop, cancel := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer cancel()
	go func() {
		<-stop.Done()
		shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), cfg.ShutdownTimeout)
		defer shutdownCancel()
		if shutdownErr := server.Shutdown(shutdownCtx); shutdownErr != nil && !errors.Is(shutdownErr, http.ErrServerClosed) {
			log.Printf("server shutdown error: %v", shutdownErr)
		}
	}()

	if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
		log.Printf("server error: %v", err)
	}
}
